INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 3, 'Gute Bewertung', 'Ich nehme die Creme erst seit ein paar Tagen, eine Verbesserung meiner Haut kann ich noch nicht feststellen, aber das dauert ja auch immer etwas… aber zumindest wird meine Haut durch die Creme nicht schlimmer was sonst oft der Fall ist (feuerrote backen)… die Verpackung und die Aufmachung finde ich wahnsinnig hochwertig und schön. Den Sinn hinter dem selber zugeben der Zusatzstoffe hab ich noch nicht ganz verstanden, aber soll wohl so ein „ich hab das selber gemacht-Gefühl“ erzeugen.. durch die einfüllung mit der Pipette bleibt halt immer ein kleiner Rest drin der dann beim raus quetschen meist neben der Creme landet.. ich bin auf jedenfall auf die Wirkung gespannt..', 'Kathrin Fischer', 'kathrin.fischer84@web.de', 'approved', '2024-12-04 23:00:00', 0, 0);
