INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Richtig gute DMS-Creme', 'Ich wollte unbedingt eine DMS-Creme als. Barrierecreme und hab sie nun gefunden. Während andere Barrierecremes auf dem Markt noch herkömmliche Emulgatoren enthalten (z.B. Glyceryl Stearate Citrate), ist hier wirklich nur Phosphatidylcholin enthalten. Auf Niacinamid, einen Wirkstoff meiner Wahl, musste ich auf Grund des individualisierten Systems auch nicht verzichten. Meine Haut verträgt die Creme bisher sehr gut!', 'Susann Goldschmidt', 'susann-g@arcor.de', 'approved', '2025-08-18 06:26:26', 0, 0);
