INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Keine Creme hat bisher gegen die Trockenen Stellen geholfen ohne dann auch alles glänzen zu lassen, meine Herbsom Creme hat das Problem behoben. Habe die 2. bestellt, die erste hielt gute 6 Monate bei 1x täglich und damit ist sie sogar gar nicht so teuer im Vergleich zu anderen, aber dabei so viel besser.', 'Liesa Demtröder', 'ldemtroeder@web.de', 'approved', '2022-08-26 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Hallo liebes Herbsom-Team, ich  in total  begeistert, meine Haut fühlt sich richtig gut versorgt  an. Benutze eure Creme vom ersten Tag an. Sagt doch wohl alles. Macht weiter. Wünsche euch viel Erfolg. Eure Heike', 'Heike Bantelmann', 'hbtm@web.de', 'approved', '2022-10-02 22:00:00', 0, 0);
