VALUES ('creme', 5, 'Gute Bewertung', 'Ich bin soo zufrieden mit dieser Creme - das ist jetzt meine zweite Bestellung. Meine Falten wurden sichtbar reduziert und der Teint ist viel ebenmäßiger. Und die Haut fühlt sich toll an nach der Pflege ✨', 'Sabrina Thillmann', 'sabrinathillmann@gmail.com', 'approved', '2022-04-15 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Ich bin absolut begeistert von der Herbsom-Creme. Meine Falten sind deutlich weniger geworden und meine Haut fühlt sich gesund und straff an. Das hatte ich schon lange nicht mehr! Ich habe direkt an meine Schwester gedacht und ihr auch einen Gutschein für eine Creme geschenkt. Das Geschenk ist extrem gut angekommen, sie war begeistert, dass sie sich die natürlichen Wirkstoffe selbst zusammenstellen kann. Jetzt ist sie auch fleißig am testen. Ich halte euch auf dem Laufenden!', 'Barbara', 'klemm.barbara@gmail.com', 'approved', '2022-04-11 22:00:00', 0, 0);
