INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Liebes Herbsome Team.
Schon das Auspacken der Creme war eine reine Freude. So liebevoll verpackt!
Ich bin sehr zufrieden mit der Creme und mit den auf meine persönlichen Bedürfnisse  abgestimmten Zusätze. 
Das Verrühren der Basiscreme mit den Zuötzen gelingt mit dem mitgelieferten Holzspatel und der Pipette sehr gut. Meine empfindliche Rosazea Haut verträgt die Creme ganz wunderbar. Mein Hautbild hat sich sehr zum Positiven verändert. Ich bin froh, Herbsome gefunden zu haben und kann die die Creme sowie die tollen Zusätze uneingeschränkt weiterempfehlen. 
Ganz lieben Dank dafür!', 'Angela Bartsch', 'bartsch-angela@t-online.de', 'approved', '2022-07-21 13:35:45', 0, 0);
